library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all; library std; use std.env.all;
entity tb_bbq_fixed_point_rescale_core is end;architecture sim of tb_bbq_fixed_point_rescale_core is signal x:std_logic_vector(15 downto 0);signal y:std_logic_vector(7 downto 0);signal o:std_logic;begin dut:entity work.bbq_fixed_point_rescale_core generic map(IN_WIDTH=>16,OUT_WIDTH=>8,SHIFT_RIGHT=>4)port map(x,y,o);process begin x<=std_logic_vector(to_signed(160,16));wait for 1 ns;assert signed(y)=10 and o='0' severity failure;x<=std_logic_vector(to_signed(4095,16));wait for 1 ns;assert signed(y)=127 and o='1' severity failure;report "PASS" severity note;stop;wait;end process;end;
